import{_ as n,o as s,c as e,a5 as p}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"54. 内联函数和标头卫生","description":"The Little Book of C 中文版 — 54. 内联函数和标头卫生","frontmatter":{"title":"54. 内联函数和标头卫生","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","06-编译与构建","中文"],"description":"The Little Book of C 中文版 — 54. 内联函数和标头卫生","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":54,"sidebarWeight":54,"alternateZh":"/posts/c教程/zh-CN/06-编译与构建/054-Inline Functions and Header Hygiene","alternateEn":"/posts/c教程/en-US/06-Compilation and Build/054-Inline Functions and Header Hygiene"},"headers":[],"relativePath":"posts/c教程/zh-CN/06-编译与构建/054-Inline Functions and Header Hygiene.md","filePath":"posts/c教程/zh-CN/06-编译与构建/054-Inline Functions and Header Hygiene.md","lastUpdated":1790163617000}'),i={name:"posts/c教程/zh-CN/06-编译与构建/054-Inline Functions and Header Hygiene.md"};function t(l,a,c,o,d,h){return s(),e("div",null,[...a[0]||(a[0]=[p(`<p>[English version](/posts/c教程/en-US/06-Compilation and Build/054-Inline Functions and Header Hygiene)</p><p>在早期的 C 中，程序员经常依赖宏来提高性能和重用。但宏有很大的缺点，没有类型检查，没有调试符号，而且错误消息很混乱。</p><p>内联函数的出现就是为了解决这个问题。它们将宏的效率与实际函数的安全性结合起来。</p><p>本节还介绍了标题卫生，或者如何编写干净、可重用的内容<code>.h</code>可在大型项目中安全扩展的文件。</p><h4 id="步骤-1-内联-是什么意思" tabindex="-1">步骤 1.“内联”是什么意思？ <a class="header-anchor" href="#步骤-1-内联-是什么意思" aria-label="Permalink to &quot;步骤 1.“内联”是什么意思？&quot;">​</a></h4><p>通常，调用类似的函数<code>add(a, b)</code>会产生少量开销，CPU 会跳转到该函数并返回。内联意味着编译器直接用函数代码替换调用，避免了跳转。</p><p>您可以使用以下建议<code>inline</code>关键词：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inline int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果使用得当，它的速度与宏一样快，但行为却像真正的函数。</p><h4 id="步骤-2-比较宏与内联函数" tabindex="-1">步骤 2. 比较宏与内联函数 <a class="header-anchor" href="#步骤-2-比较宏与内联函数" aria-label="Permalink to &quot;步骤 2. 比较宏与内联函数&quot;">​</a></h4><p>宏版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define ADD(a, b) ((a) + (b))</span></span></code></pre></div><p>内联版本：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inline int add(int a, int b) {</span></span>
<span class="line"><span>    return a + b;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>宏：</p><ul><li>没有类型检查</li><li>可能会导致多次评估（例如，<code>ADD(x++, y++)</code>)</li><li>更难调试</li></ul><p>内联函数：</p><ul><li>类型检查</li><li>单一评价</li><li>可以在调试器中逐步执行</li></ul><h4 id="步骤-3-在标头中声明内联函数" tabindex="-1">步骤 3. 在标头中声明内联函数 <a class="header-anchor" href="#步骤-3-在标头中声明内联函数" aria-label="Permalink to &quot;步骤 3. 在标头中声明内联函数&quot;">​</a></h4><p>在头文件中定义内联函数时，添加<code>static</code>为避免多重定义错误：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// math_utils.h</span></span>
<span class="line"><span>#ifndef MATH_UTILS_H</span></span>
<span class="line"><span>#define MATH_UTILS_H</span></span>
<span class="line"><span>static inline int square(int x) {</span></span>
<span class="line"><span>    return x * x;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>static inline int max(int a, int b) {</span></span>
<span class="line"><span>    return (a &gt; b) ? a : b;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>这确保了每个<code>.c</code>包含标头的文件会获得自己的副本，从而避免链接器冲突。</p><h4 id="小代码-内联实用程序" tabindex="-1">小代码：内联实用程序 <a class="header-anchor" href="#小代码-内联实用程序" aria-label="Permalink to &quot;小代码：内联实用程序&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>static inline int cube(int x) {</span></span>
<span class="line"><span>    return x * x * x;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int n = 3;</span></span>
<span class="line"><span>    printf(&quot;cube(%d) = %d\\n&quot;, n, cube(n));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cube(3) = 27</span></span></code></pre></div><p>编译器会展开<code>cube(3)</code>直接进入<code>3 * 3 * 3</code>，没有函数调用开销。</p><h4 id="步骤-4-内联和编译器" tabindex="-1">步骤 4. 内联和编译器 <a class="header-anchor" href="#步骤-4-内联和编译器" aria-label="Permalink to &quot;步骤 4. 内联和编译器&quot;">​</a></h4><p><code>inline</code>是对编译器的提示，而不是命令。编译器决定内联是否确实提高了性能。</p><p>您可以使用属性强制内联（不可移植）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__attribute__((always_inline)) inline void fast_add(int *x, int y) {</span></span>
<span class="line"><span>    *x += y;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>但最好让优化器来选择。内联过多会增加二进制大小（称为“代码膨胀”）。</p><h4 id="步骤-5-内联和联动" tabindex="-1">步骤 5. 内联和联动 <a class="header-anchor" href="#步骤-5-内联和联动" aria-label="Permalink to &quot;步骤 5. 内联和联动&quot;">​</a></h4><p>内联函数的行为根据是否声明而有所不同<code>static</code>,<code>extern</code>，或简单的<code>inline</code>.</p><table tabindex="0"><thead><tr><th>关键词组合</th><th>意义</th></tr></thead><tbody><tr><td><code>static inline</code></td><td>仅在此翻译单元中可见（对于标题安全）</td></tr><tr><td><code>extern inline</code></td><td>跨翻译单元共享（很少需要）</td></tr><tr><td><code>inline</code>（单独）</td><td>行为取决于编译器和标准版本</td></tr></tbody></table><p>坚持<code>static inline</code>对于标头定义的帮助程序。</p><h4 id="步骤-6-内联与宏-调试示例" tabindex="-1">步骤 6. 内联与宏：调试示例 <a class="header-anchor" href="#步骤-6-内联与宏-调试示例" aria-label="Permalink to &quot;步骤 6. 内联与宏：调试示例&quot;">​</a></h4><p>宏：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#define PRINT(x) printf(&quot;%d\\n&quot;, x)</span></span></code></pre></div><p>调试时的错误输出可能会显示：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>macro.c: In function &#39;main&#39;: macro.c:5: error: expected &#39;;&#39;</span></span></code></pre></div><p>排队：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>inline void print(int x) {</span></span>
<span class="line"><span>    printf(&quot;%d\\n&quot;, x);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>现在你会收到一条干净的消息：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>error: too few arguments to function &#39;print&#39;</span></span></code></pre></div><p>内联使错误处理和调试更加清晰。</p><h4 id="步骤-7-割台卫生-清洁割台的规则" tabindex="-1">步骤 7. 割台卫生，清洁割台的规则 <a class="header-anchor" href="#步骤-7-割台卫生-清洁割台的规则" aria-label="Permalink to &quot;步骤 7. 割台卫生，清洁割台的规则&quot;">​</a></h4><p>标头定义程序的公共接口。写得不好的标头会导致多重定义错误、重新定义警告和损坏的构建。</p><p>请遵循以下准则：</p><p>使用标题保护</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MYLIB_H</span></span>
<span class="line"><span>#define MYLIB_H</span></span>
<span class="line"><span>// contents</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>保持标题最少只包含必要的内容，尽可能使用前向声明。</p><p>不要放置函数定义，除非它们是<code>static inline</code>.</p><p>切勿使用<code>using namespace</code>、全局变量或标头中的大型宏。</p><p>将相关声明分组在一起：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>typedef struct Point { int x, y; } Point;</span></span>
<span class="line"><span>void move(Point *p, int dx, int dy);</span></span></code></pre></div><p>仅在需要时包含标准标头：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span><span>  // only if you use FILE*</span></span></code></pre></div><h4 id="小代码-干净的标头-实现示例" tabindex="-1">小代码：干净的标头 + 实现示例 <a class="header-anchor" href="#小代码-干净的标头-实现示例" aria-label="Permalink to &quot;小代码：干净的标头 + 实现示例&quot;">​</a></h4><p>数学库.h</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#ifndef MATHLIB_H</span></span>
<span class="line"><span>#define MATHLIB_H</span></span>
<span class="line"><span>typedef struct {</span></span>
<span class="line"><span>    int x, y;</span></span>
<span class="line"><span>} Point;</span></span>
<span class="line"><span>static inline int add(int a, int b) { return a + b; }</span></span>
<span class="line"><span>void print_point(Point p);</span></span>
<span class="line"><span>#endif</span></span></code></pre></div><p>数学库.c</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &quot;mathlib.h&quot;</span></span>
<span class="line"><span>void print_point(Point p) {</span></span>
<span class="line"><span>    printf(&quot;(%d, %d)\\n&quot;, p.x, p.y);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>主程序</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;mathlib.h&quot;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    Point p = {2, 3};</span></span>
<span class="line"><span>    print_point(p);</span></span>
<span class="line"><span>    printf(&quot;Sum = %d\\n&quot;, add(2, 5));</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>建造：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc main.c mathlib.c -o demo</span></span></code></pre></div><p>输出：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>(2, 3)</span></span>
<span class="line"><span>Sum = 7</span></span></code></pre></div><p>该结构反映了现实世界的 C 库、声明头、<code>.c</code>定义文件，以及性能重要的内联帮助程序。</p><h4 id="步骤-8-内联和优化标志" tabindex="-1">步骤 8. 内联和优化标志 <a class="header-anchor" href="#步骤-8-内联和优化标志" aria-label="Permalink to &quot;步骤 8. 内联和优化标志&quot;">​</a></h4><p>使用<code>-O2</code>或更高的优化，让编译器积极内联：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -O2 main.c -o main</span></span></code></pre></div><p>在<code>-O0</code>（没有优化），甚至内联函数也可能无法扩展。</p><h4 id="步骤-9-c99-及更高版本中的内联" tabindex="-1">步骤 9. C99 及更高版本中的内联 <a class="header-anchor" href="#步骤-9-c99-及更高版本中的内联" aria-label="Permalink to &quot;步骤 9. C99 及更高版本中的内联&quot;">​</a></h4><p>内联语义在 C99 中被标准化。较旧的编译器（C99 之前的版本）对内联的处理不一致。始终编​​译<code>-std=c99</code>或稍后的可预测行为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -std=c99 main.c -o main</span></span></code></pre></div><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>内联函数为您提供：</p><ul><li>像宏一样的性能</li><li>类型安全和清洁调试</li><li>标头中的可重用逻辑</li><li>更安全、更小的辅助功能</li></ul><p>它们是现代 C 程序员编写高效且可维护代码的最佳工具。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>将之前练习中的三个宏替换为内联函数。</li><li>使用和不使用对程序进行基准测试<code>-O2</code>看看差异。</li><li>使用以下命令编写仅包含头文件的数学库<code>static inline</code>功能。</li><li>添加标头防护并检查多个包含。</li><li>使用<code>objdump -d</code>确认您的内联代码是否确实得到了扩展。</li></ol><p>接下来，您将使用 Makefile 和构建系统（有效管理编译、链接和依赖项的工具）来自动化不断增长的 C 项目。</p>`,84)])])}const b=n(i,[["render",t]]);export{u as __pageData,b as default};
